from fractions import Fraction

def get_neighbors(r):
    neighbors = []
    # r + r' = 0 => r' = -r
    r_prime = -r
    if r_prime != r:
        neighbors.append(r_prime)
    # r + r' = 1 => r' = 1 - r
    r_prime = 1 - r
    if r_prime != r:
        neighbors.append(r_prime)
    # r * r' = 1 => r' = 1 / r
    if r != 0:
        r_prime = 1 / r
        if r_prime != r:
            neighbors.append(r_prime)
    return neighbors

def solve_f(start_val, target_vals):
    # Start BFS from start_val
    f = {start_val: 1} # f(11/3) = 1
    queue = [start_val]
    visited = {start_val}

    idx = 0
    while idx < len(queue):
        u = queue[idx]
        idx += 1
        for v in get_neighbors(u):
            if v not in f:
                f[v] = 1 - f[u]
                visited.add(v)
                queue.append(v)
            else:
                if f[v] == f[u]:
                    return None # Not 2-colorable (not bipartite)

    results = {}
    for val in target_vals:
        if val in f:
            results[val] = f[val]
        else:
            results[val] = None
    return results

