def find_distances(start_val, target_vals):
    distances = {start_val: 0}
    queue = deque([start_val])
    found = {}

    while queue:
        u = queue.popleft()
        dist = distances[u]

        if u in target_vals:
            found[u] = dist
            if len(found) == len(target_vals):
                break

        for v in get_neighbors(u):
            if v not in distances:
                distances[v] = dist + 1
                queue.append(v)
    return found

