def find_dist(start, target):
    if start == target:
        return 0

    forward_visited = {start: 0}
    backward_visited = {target: 0}
    forward_queue = deque([start])
    backward_queue = deque([target])

    while forward_queue and backward_queue:
        # Forward step
        u = forward_queue.popleft()
        d = forward_visited[u]
        for v in get_neighbors(u):
            if v in backward_visited:
                return d + 1 + backward_visited[v]
            if v not in forward_visited:
                forward_visited[v] = d + 1
                forward_queue.append(v)

        # Backward step
        u = backward_queue.popleft()
        d = backward_visited[u]
        for v in get_neighbors(u):
            if v in forward_visited:
                return d + 1 + forward_visited[v]
            if v not in backward_visited:
                backward_visited[v] = d + 1
                backward_queue.append(v)
    return None

