from fractions import Fraction

def get_neighbors(r):
    neighbors = []
    r_prime = -r
    if r_prime != r: neighbors.append(r_prime)
    r_prime = 1 - r
    if r_prime != r: neighbors.append(r_prime)
    if r != 0:
        r_prime = 1 / r
        if r_prime != r: neighbors.append(r_prime)
    return neighbors

def solve():
    start = Fraction(11, 3)
    targets = [Fraction(7, 3), Fraction(11, 4), Fraction(2024, 5), Fraction(109, 11), Fraction(3, 71), Fraction(5, 204)]

    G = nx.Graph()
    queue = [start]
    visited = {start}

    idx = 0
    while idx < len(queue):
        u = queue[idx]
        idx += 1
        for v in get_neighbors(u):
            G.add_edge(u, v)
            if v not in visited:
                visited.add(v)
                queue.append(v)
        if all(t in visited for t in targets):
            break

    f_start = 1
    results = []
    for t in targets:
        dist = nx.shortest_path_length(G, start, t)
        f_t = (f_start + dist) % 2 if dist % 2 == 0 else (1 - f_start) # This is wrong
        # f(start)=1. dist=0 => f=1, dist=1 => f=0, dist=2 => f=1
        f_t = 1 if dist % 2 == 0 else 0
        results.append(f_t)
    return results

